// steps is Z-Image-Turbo's NFE: the scheduler runs the whole stack eight
// times per image.
const steps = 8

// phase is one of the transformer's three runs over the stack, each with its
// own blocks and its own sequence length.
type phase struct {
	name   string
	blocks []int
	rows   int
}

func main() {
	log.SetFlags(0)
