		t.Helper()
		if len(got) != len(want) {
			t.Fatalf("%s: %d elements against %d", name, len(got), len(want))
		}
		bad, first := 0, -1
		for i := range got {
			if got[i] != want[i] {
				bad++
				if first < 0 {
					first = i
				}
			}
		}
		if bad != 0 {
