func TestExperimentCtxTies(t *testing.T) {
	f := loadFixture(t)
	defer f.close()
	dev, done := newTestDevice(t)
	defer done()
	x := loadRef(t, f.m, "x")
	adaln := loadRef(t, f.m, "adaln_input")
	g, err := NewGPUBlock(dev, f.blk, f.rope, f.m.Seq, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	g.FuseLayout = false
	if err := g.RunTo(x, adaln.Data, "narrow ctx"); err != nil {
		t.Fatal(err)
	}
	ctx32 := g.Read(g.TensorCtx(), g.Dim())
	unfused := g.ReadF16(g.TensorHCtx(), g.Dim(), g.LDA())
	g.FuseLayout = true
	if err := g.RunTo(x, adaln.Data, "attention"); err != nil {
		t.Fatal(err)
	}
	fused := g.ReadF16(g.TensorHCtx(), g.Dim(), g.LDA())

	// Is the fp32 value exactly halfway between two fp16 neighbours? Then and
	// only then does rounding to fp32 first change the fp16 answer.
	tie := func(v float32) bool {
		h := safetensors.F16ToF32(safetensors.F32ToF16(v))
		if h == v {
			return false
		}
		// The neighbour on the other side, and the midpoint between them.
		step := float32(math.Abs(float64(h))) / 1024
		var other float32
		if v > h {
			other = h + step
		} else {
			other = h - step
		}
		return float64(v) == (float64(h)+float64(other))/2
	}
	diff, ties, hostMatchesUnfused := 0, 0, 0
	for i := range fused.Data {
		if safetensors.F32ToF16(ctx32.Data[i]) == safetensors.F32ToF16(unfused.Data[i]) {
			hostMatchesUnfused++
		}
		if fused.Data[i] != unfused.Data[i] {
			diff++
			if tie(ctx32.Data[i]) {
				ties++
			} else if diff-ties < 4 {
				t.Logf("not a tie: fp32 %v, fused %v, unfused %v",
					ctx32.Data[i], fused.Data[i], unfused.Data[i])
			}
		}
	}
	t.Logf("%d of %d differ; %d of those are exact fp16 ties in the fp32 tensor", diff, len(fused.Data), ties)
	t.Logf("host narrowing of the fp32 tensor reproduces the unfused halves in %d of %d",
		hostMatchesUnfused, len(fused.Data))
}
