python3 - <<'PYEOF'
p='shaders/dit_attention_wmma.comp'
s=open(p).read()
old = """// It is arithmetic-preserving: the epilogue's divide by the softmax
// denominator already happens in fp32 registers, so what changes is only that
// the result is rounded once, on its way out, instead of being stored fp32
// and rounded by a second dispatch."""
new = """// It changes no arithmetic, and it removes a rounding. The divide by the
// softmax denominator already happened in fp32 registers; the old path then
// rounded that to fp32 in memory and a second dispatch rounded *that* to
// fp16, so where the fp32 result landed exactly between two halves,
// round-to-even broke a tie the fp32 rounding had manufactured. This path
// hands the store the unrounded product. 84 halves in 1.2 M come out
// differently and every one of them is such a tie, which is what
// zimage/dit's TestGPUBlockFusedLayout asserts."""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
PYEOF
cd shaders && glslc --target-env=vulkan1.2 -O -I. -DQT=1 -DKTIL=4 -DWAVE=32 -DOUT_F16=1 -o dit_attn_wmma_qt1_kt4_w32_of16.spv dit_attention_wmma.comp && cd .. && go build ./... && echo OK

python3 - <<'PYEOF'
p='zimage/dit/gpustack.go'
s=open(p).read()
old = """	// It is arithmetic-preserving and, unlike Fused, exactly so: both values
	// were already in fp32 registers at the point the old dispatch reloaded
	// them, so the same float is rounded to fp16 once either way.
	// TestGPUBlockFusedLayout checks they are bit-identical."""
new = """	// Neither changes an arithmetic operation, and the context epilogue
	// removes a rounding: v comes out bit-identical, while 84 halves in 1.2 M
	// of the context differ by one ulp because the old path rounded to fp32
	// and then to fp16 and this one rounds once. Every one of those 84 is an
	// exact fp16 tie, which is what TestGPUBlockFusedLayout asserts."""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
PYEOF
